<script setup lang="ts">
import { computed, ref } from "vue";
import { ElMessage } from "element-plus";
import { teacherGet, teacherPost, type TeacherApplication } from "../../../teacher/teacherApi";
import { formatDisplayDateTime } from "../../../lib/format";
const rows=ref<TeacherApplication[]>([]);const loading=ref(false);const handling=ref<number|null>(null);const pending=computed(()=>rows.value.filter(item=>item.status==="PENDING"));
async function load(){loading.value=true;try{rows.value=await teacherGet<TeacherApplication[]>("/api/teacher/v1/applications");}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"申请列表加载失败");}finally{loading.value=false;}}
async function handle(item:TeacherApplication,action:"approve"|"reject"){handling.value=item.id;try{await teacherPost(`/api/teacher/v1/applications/${item.id}/${action}`);ElMessage.success(action==="approve"?"已通过":"已拒绝");await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"操作失败");}finally{handling.value=null;}}
async function approveAll(){if(!pending.value.length){ElMessage.info("没有待审核的申请");return;}loading.value=true;let success=0;let fail=0;for(const item of pending.value){try{await teacherPost(`/api/teacher/v1/applications/${item.id}/approve`);success++;}catch{fail++;}}loading.value=false;ElMessage.success(`批量批准完成：成功 ${success}，失败 ${fail}`);await load();}
void load();
</script>
<template><section class="applications-page page-container"><el-card shadow="never"><template #header><div class="management-card-heading"><div class="management-card-actions"><div class="heading-actions"><el-button type="primary" :loading="loading" :disabled="!pending.length" @click="approveAll">一键批准全部（{{pending.length}}）</el-button></div></div></div></template><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="className" label="班级" min-width="150"/><el-table-column prop="displayName" label="学生" min-width="140"><template #default="{row}">{{row.displayName||row.username||'-'}}</template></el-table-column><el-table-column prop="studentNo" label="学号" min-width="130"><template #default="{row}">{{row.studentNo||'-'}}</template></el-table-column><el-table-column prop="status" label="状态" width="120"><template #default="{row}"><el-tag :type="row.status==='PENDING'?'warning':row.status==='APPROVED'?'success':'danger'">{{row.status==='PENDING'?'待审核':row.status==='APPROVED'?'已通过':'已拒绝'}}</el-tag></template></el-table-column><el-table-column prop="reason" label="备注" min-width="180"><template #default="{row}">{{row.reason||'-'}}</template></el-table-column><el-table-column label="申请时间" min-width="170"><template #default="{row}">{{formatDisplayDateTime(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><template v-if="row.status==='PENDING'"><el-button link type="primary" :loading="handling===row.id" @click="handle(row,'approve')">通过</el-button><el-button link type="danger" :loading="handling===row.id" @click="handle(row,'reject')">拒绝</el-button></template><span v-else>-</span></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无加入申请"/></el-card>
</section></template>
<style scoped>.applications-page{display:flex;flex-direction:column;gap:16px}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.page-heading h1{margin:0;font-size:22px}.page-heading p{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.page-heading>div:last-child{display:flex;gap:8px}@media(max-width:700px){.page-heading{align-items:flex-start;flex-direction:column}}</style>
